from fractions import Fraction

def cantor_pair(a: int, b: int) -> int:
    s = a + b
    return s * (s + 1) // 2 + b

def encode_int(z: int) -> int:
    return 2 * z if z >= 0 else -2 * z - 1

def encode_fraction(q: Fraction) -> int:
    return cantor_pair(encode_int(q.numerator), q.denominator)

def encode_list(items) -> int:
    acc = 0
    for x in reversed(list(items)):
        acc = 1 + cantor_pair(x, acc)
    return acc

def principal_code(conductor: int) -> int:
    g = encode_list([encode_fraction(Fraction(0))])
    return cantor_pair(cantor_pair(1, conductor), cantor_pair(g, 0))

def main() -> None:
    codes = [principal_code(n) for n in range(1, 1001)]
    print('principal L-functions encoded:', len(codes))
    print('all codes distinct:', len(set(codes)) == len(codes))
    print('first ten codes:', codes[:10])

if __name__ == '__main__':
    main()

from typing import List

def euler_totient(n: int) -> int:
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result

def cantor_diagonal(seqs: List[List[int]]) -> List[int]:
    return [1 - seqs[i][i] for i in range(len(seqs))]

def main() -> None:
    for bound in (10, 50, 100):
        total = sum(euler_totient(n) for n in range(1, bound + 1))
        print(f'Dirichlet characters, moduli 1..{bound}: {total} (finite)')
    listing = [[(i >> k) & 1 for k in range(6)] for i in range(6)]
    missing = cantor_diagonal(listing)
    print('diagonal per-prime labelling not in list:', missing)

if __name__ == '__main__':
    main()

