from fractions import Fraction
from typing import Iterable

def cantor_pair(a: int, b: int) -> int:
    """Bijection N x N -> N."""
    s = a + b
    return s * (s + 1) // 2 + b

def encode_int(z: int) -> int:
    """Bijection Z -> N: 0,-1,1,-2,2,... -> 0,1,2,3,4,..."""
    return 2 * z if z >= 0 else -2 * z - 1

def encode_fraction(q: Fraction) -> int:
    """Bijection Q -> N."""
    return cantor_pair(encode_int(q.numerator), q.denominator)

def encode_list(items: Iterable[int]) -> int:
    """Bijection (finite lists over N) -> N via iterated pairing."""
    acc = 0
    for x in reversed(list(items)):
        acc = 1 + cantor_pair(x, acc)
    return acc

def encode_signature(degree: int, conductor: int,
                     gamma_shifts: tuple[Fraction, ...],
                     euler_factors: tuple[tuple[int, tuple[Fraction, ...]], ...]) -> int:
    """Injective Goedel code of an arithmetic signature into N.

    Witnesses countability: distinct signatures receive distinct naturals.
    """
    g = encode_list(encode_fraction(x) for x in gamma_shifts)
    e = encode_list(
        cantor_pair(p, encode_list(encode_fraction(c) for c in coeffs))
        for (p, coeffs) in euler_factors
    )
    return cantor_pair(cantor_pair(degree, conductor), cantor_pair(g, e))

