def euler_totient(n: int) -> int:
    """Euler's totient phi(n) = number of Dirichlet characters modulo n."""
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result

def dirichlet_partial_census(max_modulus: int) -> int:
    """Total Dirichlet characters over all moduli 1..max_modulus (finite)."""
    return sum(euler_totient(n) for n in range(1, max_modulus + 1))
